// Select one operation, then click Execute Workflow.
// authorize | exchange | refresh | merchant | ping | payment | order_types | create_order
const settings = {
  operation: 'authorize',
  sandboxAppId: 'X428N4RYRG5S8',
  oauthCallbackUrl: '', // Paste the Capture Clover Sandbox Callback node's Test URL.
  sandboxMerchantId: '',
  sandboxRemoteAppId: '',
  sandboxDeviceSerial: '',
  paymentAttemptId: '', // A UUID. Reuse for a retry, replace for a NEW payment.
  sandboxOrderTypeId: '', // Optional original atomic-order experiment.
};

const operations = ['authorize', 'exchange', 'refresh', 'merchant', 'ping', 'payment', 'order_types', 'create_order'];
if (!operations.includes(settings.operation)) {
  throw new Error('Choose a supported operation listed above the settings.');
}
if (settings.operation === 'authorize' && (!settings.oauthCallbackUrl.startsWith('https://') || !settings.oauthCallbackUrl.includes('/webhook-test/'))) {
  throw new Error('Paste the callback Webhook Test URL into oauthCallbackUrl. Use the Test URL for this manual capture.');
}
const merchantOperations = ['merchant', 'order_types', 'create_order'];
if (merchantOperations.includes(settings.operation) && !/^[A-Z0-9]{13}$/.test(settings.sandboxMerchantId)) {
  throw new Error('Enter the 13-character SANDBOX test merchant ID in Sandbox Settings.');
}
if (['ping', 'payment'].includes(settings.operation)) {
  if (!settings.sandboxRemoteAppId.trim() || !/^[A-Z0-9]{14}$/.test(settings.sandboxDeviceSerial)) {
    throw new Error('Enter the sandbox app RAID and sandbox Dev Kit serial in Sandbox Settings.');
  }
}
if (settings.operation === 'payment' && !/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(settings.paymentAttemptId)) {
  throw new Error('Enter a UUID as paymentAttemptId. Keep it for retries of the same payment.');
}
if (settings.operation === 'create_order' && !/^[A-Z0-9]{13}$/.test(settings.sandboxOrderTypeId)) {
  throw new Error('Enter an enabled SANDBOX order type ID before creating an order.');
}
return [{ json: settings }];

const settings = $input.first().json;
return [{ json: {
  authorizationUrl: 'https://sandbox.dev.clover.com/oauth/v2/authorize?client_id='
    + encodeURIComponent(settings.sandboxAppId)
    + '&response_type=code&redirect_uri=' + encodeURIComponent(settings.oauthCallbackUrl),
  nextStep: 'Set the sandbox app Site URL to oauthCallbackUrl. Click Listen for test event on Capture Clover Sandbox Callback, then open authorizationUrl in your browser and authorize the intended sandbox merchant.'
} }];

const query = $input.first().json.query || {};
if (query.error) {
  throw new Error('Clover returned an authorization error. Inspect the callback query in the Webhook node.');
}
if (typeof query.code !== 'string' || !query.code.trim()) {
  throw new Error('Clover callback has no authorization code. Open the generated /oauth/v2/authorize link while the test listener is active.');
}
if (query.client_id && query.client_id !== 'X428N4RYRG5S8') {
  throw new Error('The callback is for a different Clover app.');
}
return [{ json: {
  authorizationCode: query.code,
  sandboxMerchantId: query.merchant_id || query.merchantId || '',
  nextStep: 'Verify this is the intended sandbox merchant. Privately copy authorizationCode into the Token Exchange Custom Auth credential as body.code. Run operation exchange promptly. Keep this output out of recordings.'
} }];
